m=np.arange(1,25);target=np.full(24,.7);slow=.45+.01*m;fast=1.2-.01*m;ax.plot(m,target,color=GOOD,lw=2,label='PAC target');ax.plot(m,slow,color=BAD,label='Slow collateral: shortfall');ax.plot(m,fast,color=ACCENT,label='Fast collateral: excess');ax.fill_between(m,slow,target,where=slow<target,color=BAD,alpha=.15);ax.set_xlabel('Month');ax.set_ylabel('Principal available (USD M)');ax.set_title('Cash available limits the PAC payment',loc='left');ax.legend(fontsize=8);ax.grid(alpha=.25)
